import type { McpServer } from "@modelcontextprotocol/server";
import { RESOURCE_MIME_TYPE, registerAppResource } from "@modelcontextprotocol/ext-apps/server";
// Generated by `npm run build:ui` (scripts/build-ui.mjs). Imported as a module, not read from
// disk, so it ships inside serverless bundles.
import quizHtml from "./generated/quiz-html";

/** The interactive quiz view. Tools that display a quiz point at this URI via `_meta.ui.resourceUri`. */
export const QUIZ_UI_URI = "ui://education/quiz.html";

export function registerUiResources(server: McpServer): void {
  registerAppResource(
    server,
    "Interactive Quiz",
    QUIZ_UI_URI,
    { description: "Clickable multiple-choice quiz with instant feedback and a final score." },
    async () => ({
      contents: [{ uri: QUIZ_UI_URI, mimeType: RESOURCE_MIME_TYPE, text: quizHtml }],
    }),
  );
}
